    # GGML's 18-byte Q4 blocks alternate between two- and four-byte alignment.
    return f'T.call_extern("uint32", "tensor_byte_align_u32", w[({address}) // 4], w[(({address}) + 3) // 4], T.cast(({address}) % 4, "uint32"))'


